const header=document.querySelector(".site-header");const menuBtn=document.querySelector(".menu-btn");const mobile=document.querySelector(".mobile-panel");function onScroll(){if(scrollY>30)header?.classList.add("scrolled");else header?.classList.remove("scrolled")}onScroll();addEventListener("scroll",onScroll,{passive:true});menuBtn?.addEventListener("click",()=>{const open=mobile.classList.toggle("open");menuBtn.setAttribute("aria-expanded",String(open));document.body.classList.toggle("no-scroll",open)});const reviews=[...document.querySelectorAll(".review")];const dots=[...document.querySelectorAll(".dot")];dots.forEach((d,i)=>d.addEventListener("click",()=>{reviews.forEach(r=>r.classList.remove("active"));dots.forEach(x=>x.classList.remove("active"));reviews[i]?.classList.add("active");d.classList.add("active")}));
